import K from './pgadynData.js';
import BENCH from './benchData.js';
import { ROWS } from './rigidRows.js';

// Copy for step 13 of the equations page (English and Italian): a rigid body in the bit-rule algebra, from the segment to the tesseract, then the free top, the Moon and the planets.
// Every count comes from selfcheck/pgadyn.json (exact rational arithmetic, standard library); every speed from selfcheck/bench_labels.json (timed, on one machine).
const S = K.summary, ROWN = S.rows;
export const THREADS = ['segment', 'square', 'cube', 'hang', 'frame', 'top', 'orbits'];
// where each row of the check lives, and whether the identity is textbook (standard) or the arrangement is ours
export const ROW_META = {
  A1: ['cube', 'ours'], A2: ['cube', 'standard'], A3: ['cube', 'ours'], A4: ['cube', 'standard'], A5: ['cube', 'ours'], A6: ['segment', 'standard'], A7: ['frame', 'standard'],
  B1: ['segment', 'standard'], B2: ['segment', 'standard'], B3: ['segment', 'standard'], B4: ['segment', 'ours'],
  C1: ['square', 'standard'], E9: ['square', 'standard'], N7: ['square', 'standard'],
  D1: ['cube', 'standard'], D2: ['cube', 'standard'], D3: ['cube', 'standard'], D4: ['cube', 'standard'],
  E1: ['cube', 'standard'], E2: ['cube', 'standard'], E3: ['cube', 'standard'], E6: ['cube', 'standard'], F1: ['cube', 'standard'], F2: ['cube', 'standard'], R1: ['cube', 'standard'], R2: ['cube', 'standard'],
  E4: ['hang', 'standard'], E5: ['hang', 'standard'], E7: ['hang', 'standard'], E8: ['hang', 'standard'], E10: ['hang', 'standard'], E11: ['hang', 'ours'], E12: ['hang', 'standard'],
  R3: ['hang', 'standard'], R4: ['hang', 'standard'], R5: ['hang', 'standard'], R6: ['hang', 'standard'],
  G1: ['frame', 'ours'], G2: ['frame', 'ours'], G3: ['frame', 'ours'], G4: ['frame', 'ours'], G5: ['frame', 'ours'],
  T1: ['top', 'standard'], T2: ['top', 'standard'], T3: ['top', 'standard'], R7: ['top', 'standard'], R8: ['top', 'ours'],
  N1: ['orbits', 'standard'], N2: ['orbits', 'standard'], N3: ['orbits', 'standard'], N4: ['orbits', 'standard'], N5: ['orbits', 'standard'], N6: ['orbits', 'standard'], N8: ['orbits', 'standard'], N9: ['orbits', 'standard'], R9: ['orbits', 'standard'],
};
export const CONTROLS = ['A5', 'B4', 'E2', 'E5', 'E11', 'E12', 'N1', 'N3', 'N4', 'T2'];
// rows that are not plain exact proofs say so in their badge
export const STATUS = { N9: 'plaus', R1: 'ref', R2: 'ref', R3: 'ref', R4: 'ref', R5: 'ref', R6: 'ref', R7: 'ref', R9: 'ref', R8: 'obs' };
export const rowText = (lang, id) => { const r = ROWS[id][lang === 'it' ? 'it' : 'en']; return { claim: r[0], inst: r[1] }; };
const nat = id => id[0].charCodeAt(0) * 100 + Number(id.slice(1));
export const rowIds = K.rows.map(r => r.id).sort((a, b) => nat(a) - nat(b));

// the timings, as measured when the page was built: ratios of medians, machine dependent
const bn = n => BENCH.rows.find(r => r.n === n), ratio = (n, a, b) => bn(n).ns[a].med / bn(n).ns[b].med;
const span = (ns, a, b) => { const v = ns.map(n => ratio(n, a, b)); return [Math.min(...v), Math.max(...v)]; };
const num = (v, l) => (v >= 10 ? v.toFixed(0) : v.toFixed(2)).replace('.', l === 'it' ? ',' : '.') + '×';
const rg = ([a, b], l) => `${num(a, l)}–${num(b, l)}`;
const M = BENCH.machine;
export const BENCH_FACTS = {
  frame: [1, 2, 3, 4, 5, 6].map(n => ratio(n, 'direct', 'frame')),
  matrix: span([3, 4, 5, 6], 'matrixGiven', 'doubling'), mirror: span([2, 3, 4, 5, 6], 'frame', 'mirror'),
  scanGiven: span([1, 2, 3, 4, 5, 6], 'scan', 'bits'), scanBuilt: span([1, 2, 3, 4, 5, 6], 'scanBuilt', 'bitsBuilt'),
  hullGiven: span([2, 3, 4, 5, 6], 'hull', 'zono'), hullBuilt: span([2, 3, 4, 5, 6], 'hullBuilt', 'zonoBuilt'),
};
const BF = BENCH_FACTS;
const benchEn = `Timed, not proved. On one machine (${M.cpu}, ${M.cores} cores, node ${M.node}, ${M.date}), building the world vertices from the frame instead of with one sandwich each had a relative speed of ${num(BF.frame[0], 'en')} at n = 1 and ${num(BF.frame[1], 'en')} at n = 2 (no gain), then ${num(BF.frame[2], 'en')}, ${num(BF.frame[3], 'en')}, ${num(BF.frame[4], 'en')}, ${num(BF.frame[5], 'en')} at n = 3…6. Reflecting half the table through the centre: ${rg(BF.mirror, 'en')}, so no gain. Reading the deepest vertex from n sign bits instead of scanning a given table: ${rg(BF.scanGiven, 'en')}; once the table has to be built as well: ${rg(BF.scanBuilt, 'en')}. The outline from n edges instead of a hull: ${rg(BF.hullGiven, 'en')} on given points, ${rg(BF.hullBuilt, 'en')} with the building. A value above 1 means the label way was faster. Batches of at least ${M.minMs} ms, median of ${M.reps}, spread about 5 %. Press the button on the Timing tab to measure your own device.`;
const benchIt = `Misurato, non dimostrato. Su una macchina (${M.cpu}, ${M.cores} core, node ${M.node}, ${M.date}), costruire i vertici nel mondo dal telaio invece che con un sandwich ciascuno ha avuto una velocità relativa di ${num(BF.frame[0], 'it')} a n = 1 e ${num(BF.frame[1], 'it')} a n = 2 (nessun guadagno), poi ${num(BF.frame[2], 'it')}, ${num(BF.frame[3], 'it')}, ${num(BF.frame[4], 'it')}, ${num(BF.frame[5], 'it')} per n = 3…6. Riflettere mezza tabella attraverso il centro: ${rg(BF.mirror, 'it')}, quindi nessun guadagno. Leggere il vertice più profondo da n bit di segno invece di scorrere una tabella data: ${rg(BF.scanGiven, 'it')}; quando la tabella va costruita anch’essa: ${rg(BF.scanBuilt, 'it')}. Il contorno da n spigoli invece che da un inviluppo: ${rg(BF.hullGiven, 'it')} su punti dati, ${rg(BF.hullBuilt, 'it')} con la costruzione. Un valore sopra 1 significa che il modo con le etichette era più veloce. Lotti di almeno ${M.minMs} ms, mediana di ${M.reps}, dispersione circa il 5 %. Premi il pulsante nella scheda Tempi per misurare il tuo dispositivo.`;

